#include <bits/stdc++.h>
using namespace std;
#ifndef MODULUS
#define MODULUS 32749
#endif
const int P=MODULUS;int mod(long long x){x%=P;if(x<0)x+=P;return x;}int mul(int a,int b){return (long long)a*b%P;}int pw(int a,int e){int r=1;while(e){if(e&1)r=mul(r,a);a=mul(a,a);e>>=1;}return r;}vector<int>pmul(vector<int>a,vector<int>b){vector<int>o(a.size()+b.size()-1);for(int i=0;i<(int)a.size();i++)for(int j=0;j<(int)b.size();j++)o[i+j]=mod(o[i+j]+(long long)a[i]*b[j]);return o;}int Cb[100][100],Pow[40][120];int basis(int a,int b,int r,int v,int sh,int i,int j){if(j>b)return 0;int o=0;for(int z=0;z<=b-j;z++)if(i>=z&&i-z<=a)o=mod(o+(long long)Cb[b][j]*Cb[b-j][z]%P*Pow[v][b-j-z]%P*Pow[sh][z]%P*Cb[a][i-z]%P*Pow[r][a-i+z]);return o;}struct RC{vector<int>w,h;};
int main(int argc,char**argv){if(argc!=4)return 2;int q=stoi(argv[3]),D=2*q,nq=(q-2)*(q-2),K=nq+1;for(int n=0;n<100;n++){Cb[n][0]=Cb[n][n]=1;for(int k=1;k<n;k++)Cb[n][k]=mod(Cb[n-1][k-1]+Cb[n-1][k]);}for(int a=0;a<40;a++){Pow[a][0]=1;for(int b=1;b<120;b++)Pow[a][b]=mul(Pow[a][b-1],a);}vector<pair<int,int>>mons;for(int b=q-3;b>=0;b--)for(int a=D-6-2*b;a>=0;a--)mons.push_back({a,b});if((int)mons.size()!=nq)throw runtime_error("dim");vector<int>W{1};for(int r=3;r<=8;r++)W=pmul(W,{mod(-r),1});vector<vector<int>>L;for(int r=3;r<=8;r++){vector<int>l{1};int den=1;for(int s=3;s<=8;s++)if(s!=r){l=pmul(l,{mod(-s),1});den=mul(den,mod(r-s));}int iv=pw(den,P-2);for(int&x:l)x=mul(x,iv);L.push_back(l);}map<array<int,4>,RC>cache;auto get=[&](int r,int ss,int i,int j)->RC&{array<int,4>key{r,ss,i,j};auto it=cache.find(key);if(it!=cache.end())return it->second;auto&R=cache[key];int v=ss*(r-ss),sh=(2*ss==r?ss:0);for(auto[a,b]:mons){int c=0;for(int tt=0;tt<=6;tt++)c=mod(c+(long long)W[tt]*basis(a+tt,b,r,v,sh,i,j));R.w.push_back(c);}for(int b=0;b<=q;b++)for(int a=0;a<6;a++)R.h.push_back(basis(a,b,r,v,sh,i,j));return R;};ifstream in(argv[1]);ofstream out(argv[2]);string line;int count=0,full=0,low=0;while(getline(in,line)){istringstream is(line);int qq,z,lam5,lam8;is>>qq>>z>>lam5>>lam8;if(qq!=q)throw runtime_error("q");vector<vector<int>>mm(6);for(int r=3;r<=8;r++){mm[r-3].resize(r/2+1);for(int&m:mm[r-3])is>>m;}vector<int>h0(6*(q+1));for(int r=3;r<=8;r++){vector<int>row{1};for(int ss=0;ss<=r/2;ss++)for(int k=0;k<mm[r-3][ss];k++)row=pmul(row,{mod(-ss*(r-ss)),1});if(r==5)row=pmul(row,{mod(-lam5),1});if(r==8)row=pmul(row,{mod(-lam8),1});if((int)row.size()!=q+1)throw runtime_error("degree");for(int b=0;b<=q;b++)for(int a=0;a<6;a++)h0[6*b+a]=mod(h0[6*b+a]+(long long)row[b]*L[r-3][a]);}for(int b=0;b<=q;b++)for(int a=0;a<6;a++)if(a+2*b>D&&h0[6*b+a])throw runtime_error("weight");vector<vector<int>>B(K);int rank=0,det=1;vector<int>ids;for(int r=3;r<=8&&rank<K;r++)for(int ss=0;ss<=r/2&&rank<K;ss++){int m=mm[r-3][ss];bool dg=2*ss==r;int lim=dg?2*m:m;for(int w=1;w<lim&&rank<K;w++)for(int j=0;j<=w/(dg?2:1)&&rank<K;j++){int i=w-(dg?2:1)*j;if(!i)continue;auto&R=get(r,ss,i,j);vector<int>x=R.w;long long last=0;for(int k=0;k<(int)h0.size();k++)last+=(long long)h0[k]*R.h[k];x.push_back(last%P);for(int col=0;col<K;col++){int cc=x[col];if(!cc)continue;if(B[col].empty()){int iv=pw(cc,P-2);det=mul(det,cc);for(int k=col;k<K;k++)x[k]=mul(x[k],iv);B[col]=move(x);rank++;ids.push_back(r*100000+ss*10000+i*100+j);break;}else for(int k=col;k<K;k++)x[k]=mod(x[k]-(long long)cc*B[col][k]);}}}if(rank==K)full++;else{low++;cerr<<"LOW "<<count<<" rank "<<rank<<" "<<line<<"\n";}out<<count<<' '<<rank<<' '<<det;for(int x:ids)out<<' '<<x;out<<'\n';count++;}cerr<<"q "<<q<<" count "<<count<<" full "<<full<<" low "<<low<<"\n";cout<<"DOUBLE58_JETS q "<<q<<" count "<<count<<" full "<<full<<" low "<<low<<"\n";}
